internal fun estonianMatchingCount(count: Int, noun: String): String {
    val adjective = if (count == 1) "sobiv" else "sobivat"
    return "$count $adjective ${localizedCountLabel(count, noun, AppLanguage.Estonian).substringAfter(' ')}"
}
